import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    idx = 0
    operation = data[idx]; idx += 1
    value_type = data[idx]; idx += 1
    n = int(data[idx]); idx += 1
    values = []
    for i in range(n):
        if idx < len(data):
            values.append(int(data[idx]))
            idx += 1

    if operation == "sum":
        result = sum(values)
    elif operation == "max":
        result = max(values)
    elif operation == "average":
        result = sum(values) / len(values)

    # Check if result is integer
    if isinstance(result, float) and result == int(result):
        print(int(result))
    else:
        print(result)

if __name__ == "__main__":
    main()
